SELECT o.*, u.username as customerName, u.phone as customerPhone
FROM t_order o
LEFT JOIN t_user u ON o.customer_id = u.id

    o.deleted = 0
    AND o.customer_id = #{dto.customerId}
    AND o.order_no LIKE CONCAT('%', #{dto.orderNo}, '%')
    AND u.username LIKE CONCAT('%', #{dto.customerName}, '%')
    AND o.status = #{dto.status}
     AND o.total_amount >= #{dto.minAmount} 
     AND o.total_amount <= #{dto.maxAmount} 
     AND o.create_time >= #{dto.startTime} 
     AND o.create_time <= #{dto.endTime} 

ORDER BY

    o.total_amount
    o.total_quantity
    o.create_time
    o.create_time


    ASC
    DESC

SELECT o.*, u.username as customerName, u.phone as customerPhone
FROM t_order o
LEFT JOIN t_user u ON o.customer_id = u.id

    o.deleted = 0
    AND o.customer_id = #{dto.customerId}
    AND o.seller_id = #{dto.sellerId}
    AND o.order_no LIKE CONCAT('%', #{dto.orderNo}, '%')
    AND u.username LIKE CONCAT('%', #{dto.customerName}, '%')
    AND o.status = #{dto.status}
     AND o.total_amount >= #{dto.minAmount} 
     AND o.total_amount <= #{dto.maxAmount} 
     AND o.create_time >= #{dto.startTime} 
     AND o.create_time <= #{dto.endTime} 

ORDER BY

    o.total_amount
    o.total_quantity
    o.create_time
    o.create_time


    ASC
    DESC

SELECT customer_id AS userId, COUNT(*) AS orderCount, SUM(total_amount) AS totalAmount, MAX(create_time) AS lastOrderTime FROM `t_order` WHERE seller_id = #{sellerId} AND customer_id IN
#{uid}
GROUP BY customer_id
